-- The Dev queue (docs/plan.md §1.125, owner 2026-11-17): the Builder's requests for code, the
-- builds and steps waiting on each, and each request's history; and a to-do (and a play log row)
-- may now be about a request, for the back-office notice when one is accepted or shipped. New
-- tables and a widened check only, so the previous Worker keeps working (it never reads the
-- tables, and every about kind it writes is still allowed). Generated by drizzle-kit; the grants,
-- row-level security and append-only triggers at the end are hand-written.
CREATE TABLE "code_request" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"number" integer GENERATED BY DEFAULT AS IDENTITY (sequence name "code_request_number_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"title" text NOT NULL,
	"kind" text NOT NULL,
	"status" text DEFAULT 'triage' NOT NULL,
	"spec" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"open_questions" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"reuse_check" jsonb,
	"decision" text,
	"decision_reason" text,
	"other_uses" text[] DEFAULT '{}'::text[] NOT NULL,
	"one_off_approved_by" uuid,
	"one_off_approved_at" timestamp with time zone,
	"merged_into_id" uuid,
	"close_reason" text,
	"owner" text,
	"claimed_by" uuid,
	"claimed_at" timestamp with time zone,
	"pr_url" text,
	"expected_part_id" text,
	"shipped_part_id" text,
	"shipped_staging_at" timestamp with time zone,
	"shipped_production_at" timestamp with time zone,
	"created_by" text NOT NULL,
	"created_by_user" uuid,
	"last_event_at" timestamp with time zone DEFAULT now() NOT NULL,
	"closed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "code_request_number_key" UNIQUE("number"),
	CONSTRAINT "code_request_title_check" CHECK (char_length("code_request"."title") between 1 and 200),
	CONSTRAINT "code_request_kind_check" CHECK ("code_request"."kind" in ('extend_existing', 'new_tool', 'new_skill_code', 'config_only')),
	CONSTRAINT "code_request_status_check" CHECK ("code_request"."status" in ('triage', 'accepted', 'in_progress', 'shipped', 'closed')),
	CONSTRAINT "code_request_decision_check" CHECK ("code_request"."decision" is null or "code_request"."decision" in ('exists', 'config', 'extend', 'new_general', 'one_off')),
	CONSTRAINT "code_request_close_reason_check" CHECK ("code_request"."close_reason" is null or "code_request"."close_reason" in ('exists', 'config', 'merged', 'not_worth_it', 'not_possible', 'superseded')),
	CONSTRAINT "code_request_created_by_check" CHECK ("code_request"."created_by" in ('builder', 'operator', 'session')),
	CONSTRAINT "code_request_closed_check" CHECK (("code_request"."status" = 'closed') = ("code_request"."close_reason" is not null)),
	CONSTRAINT "code_request_merged_check" CHECK (("code_request"."close_reason" = 'merged') = ("code_request"."merged_into_id" is not null)),
	CONSTRAINT "code_request_not_self_check" CHECK ("code_request"."merged_into_id" is null or "code_request"."merged_into_id" <> "code_request"."id")
);
