-- Row-level security, forced: a request is the operator's and global, like an enhancement; a
-- client's session never sees one. A link is visible only with its build (held to build's own
-- policy, so only for builds of the clients the session serves, or of no client).
ALTER TABLE code_request ENABLE ROW LEVEL SECURITY;
